34	     * read-only {@code displayName} field returned on the Owner DTO.
35	     */
36	    default String toDisplayName(Owner owner) {
37	        return owner.getLastName() + ", " + owner.getFirstName();
38	    }
39	
40	    /**
41	     * Build the owner's initials as the upper-cased first letters of firstName and
42	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}) for the
43	     * read-only {@code initials} field returned on the Owner DTO.
44	     */
45	    default String toInitials(Owner owner) {
46	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
47	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
48	    }
49	
50	    /**
51	     * Derive the owner's read-only {@code locality}: the region resolved from the owner's postcode
52	     * range first ({@code NSW 2000-2099, VIC 3000-3099, QLD 4000-4099}), falling back to the
53	     * canonical region looked up from the owner's city in the fixed city-to-region table
54	     * ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}) when the postcode is absent or in no
55	     * known range, or {@code 'UNKNOWN'} when neither yields a region. Preferring the postcode
56	     * disambiguates cities that share a name while returning the same region for known cities.
57	     */
58	    default String toLocality(Owner owner) {
59	        String region = PostcodeRules.regionOfPostcode(owner.getPostcode());
60	        if (region == null) {
