70	    default OwnerDto.ContactPreferenceEnum toContactPreference(Owner owner) {
71	        return owner.getEmail() != null && !owner.getEmail().isBlank()
72	            ? OwnerDto.ContactPreferenceEnum.EMAIL
73	            : OwnerDto.ContactPreferenceEnum.PHONE;
