85	    /**
86	     * Normalize a postal address to its canonical form (trimmed and whitespace-collapsed,
87	     * upper-cased, with common street-type abbreviations expanded) so it is stored, returned and
88	     * compared in one shape. Blank-after-normalization is rejected separately by
89	     * {@code AddressValidation} on the inbound DTO, so this only performs the transform the stored
90	     * value needs.
91	     */
92	    @Named("normalizeAddress")
93	    default String normalizeAddress(String address) {
94	        return AddressNormalizer.normalize(address);
95	    }
96	
97	    /**
98	     * Normalize a telephone number to canonical E.164 form (a leading {@code '+'}, country
99	     * code and national digits) so it is stored and returned in one comparable form and
100	     * duplicates can be detected by comparing these values. Format validity is enforced
101	     * separately by {@code TelephoneValidation} on the inbound DTO, so this only performs
102	     * the transform the stored value needs.
103	     */
104	    @Named("normalizeTelephone")
105	    default String normalizeTelephone(String telephone) {
106	        return TelephoneNormalizer.toE164(telephone);
107	    }
108	
109	    /**
110	     * Normalize an email address by trimming surrounding whitespace and lower-casing
111	     * it so it is stored and returned in a canonical form. Syntactic validity is
112	     * enforced separately by {@code @Email} on the inbound DTO, so this only performs
113	     * the transform the stored value needs.
114	     */
115	    @Named("normalizeEmail")
116	    default String normalizeEmail(String email) {
117	        return email == null ? null : email.trim().toLowerCase();
118	    }
119	
120	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
121	
122	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
123	
124	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
125	        OwnerPageDto ownerPageDto = new OwnerPageDto();
126	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
127	        ownerPageDto.setPage(ownerPage.getNumber());
128	        ownerPageDto.setSize(ownerPage.getSize());
129	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
130	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
131	        return ownerPageDto;
132	    }
133	}
