16	@Constraint(validatedBy = PostcodeValidator.class)
17	@Documented
18	public @interface PostcodeValidation {
19	
20	    String message() default "Postcode is not valid for the owner's city";
21	
22	    Class<?>[] groups() default {};
23	
24	    Class<? extends Payload>[] payload() default {};
25	}
