3	import jakarta.validation.ConstraintValidator;
4	import jakarta.validation.ConstraintValidatorContext;
5	
6	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
7	
8	/**
9	 * Validates that a telephone number can be normalized to a valid E.164 number (a leading
10	 * {@code '+'} followed by 8 to 15 digits). The check delegates to {@link TelephoneNormalizer},
11	 * the same normalization applied by {@code OwnerMapper}, so a value that passes this constraint
12	 * is exactly one that normalizes to the E.164 form that gets stored. A {@code null} value is
13	 * left to {@code @NotBlank}.
